/* global process */
/**
 * Research Trellis Context Injection Plugin
 *
 * Generated by `rt init`. Safe to edit; repeated init preserves this file.
 * Non-mutating: reads RT state/source files, then injects bounded context into
 * RT role-agent Task calls and lightweight main-chat breadcrumbs.
 */

import { existsSync, readFileSync } from "fs"
import { join } from "path"

const RT_MARKER = "<!-- rt-context-injected -->"

function readText(filePath) {
  try {
    return existsSync(filePath) ? readFileSync(filePath, "utf-8") : null
  } catch {
    return null
  }
}

function isRtRepo(directory) {
  return existsSync(join(directory, ".research-trellis")) && existsSync(join(directory, "research", "project.md"))
}

function parseScalar(value) {
  const trimmed = String(value || "").trim()
  if (trimmed === "null" || trimmed === "") return null
  if (/^-?\d+$/.test(trimmed)) return Number(trimmed)
  return trimmed.replace(/^['"]|['"]$/g, "")
}

function parseSimpleYamlMap(content) {
  const result = {}
  for (const line of String(content || "").split(/\r?\n/)) {
    const match = /^(\w[\w_-]*):\s*(.*?)\s*$/.exec(line)
    if (match) result[match[1]] = parseScalar(match[2])
  }
  return result
}

function parseThreadFrontmatter(content) {
  const match = /^---\n([\s\S]*?)\n---/.exec(String(content || "").replace(/\r\n/g, "\n"))
  return match ? parseSimpleYamlMap(match[1]) : {}
}

function parseConfig(content) {
  const config = { maturity_ladder: [], roles: {} }
  let section = null
  let role = null
  let listKey = null

  for (const rawLine of String(content || "").split(/\r?\n/)) {
    const line = rawLine.replace(/\t/g, "  ")
    const trimmed = line.trim()
    if (!trimmed || trimmed.startsWith("#")) continue

    if (/^maturity_ladder:\s*$/.test(trimmed)) {
      section = "maturity_ladder"
      role = null
      listKey = null
      continue
    }
    if (/^roles:\s*$/.test(trimmed)) {
      section = "roles"
      role = null
      listKey = null
      continue
    }
    if (section === "maturity_ladder" && /^-\s+/.test(trimmed)) {
      config.maturity_ladder.push(parseScalar(trimmed.slice(2)))
      continue
    }
    if (section !== "roles") continue

    const roleMatch = /^\s{2}([A-Za-z0-9_-]+):\s*$/.exec(line)
    if (roleMatch) {
      role = roleMatch[1]
      config.roles[role] = { warnings: [], prompt: { stop_conditions: [] } }
      listKey = null
      continue
    }
    if (!role) continue
    const currentRole = config.roles[role]
    const scalarMatch = /^\s{4}(min_maturity|min_readiness):\s*(.*?)\s*$/.exec(line)
    if (scalarMatch) {
      currentRole[scalarMatch[1]] = parseScalar(scalarMatch[2])
      listKey = null
      continue
    }
    if (/^\s{4}warnings:\s*$/.test(line)) {
      listKey = "warnings"
      continue
    }
    if (/^\s{4}prompt:\s*$/.test(line)) {
      listKey = null
      continue
    }
    const objectiveMatch = /^\s{6}objective:\s*(.*?)\s*$/.exec(line)
    if (objectiveMatch) {
      currentRole.prompt.objective = parseScalar(objectiveMatch[1])
      continue
    }
    if (/^\s{6}stop_conditions:\s*$/.test(line)) {
      listKey = "stop_conditions"
      continue
    }
    const listMatch = /^\s{4,8}-\s+(.*?)\s*$/.exec(line)
    if (listMatch && listKey === "warnings") {
      currentRole.warnings.push(parseScalar(listMatch[1]))
      continue
    }
    if (listMatch && listKey === "stop_conditions") {
      currentRole.prompt.stop_conditions.push(parseScalar(listMatch[1]))
    }
  }

  return config
}

function roleNameFromTaskArgs(args) {
  const candidates = [args?.subagent_type, args?.subagentType, args?.agent, args?.agent_name, args?.name]
  for (const candidate of candidates) {
    if (typeof candidate !== "string") continue
    const match = /^rt-([A-Za-z0-9_-]+)$/.exec(candidate.trim())
    if (match) return match[1]
  }
  return null
}

function roleFromTaskArgs(args, config) {
  const roleName = roleNameFromTaskArgs(args)
  if (!roleName) return null
  return Object.prototype.hasOwnProperty.call(config.roles || {}, roleName) ? roleName : null
}

function gateWarnings(roleConfig, config, thread) {
  const warnings = [...(roleConfig?.warnings || [])]
  const readiness = typeof thread.readiness === "number" ? thread.readiness : Number(thread.readiness)
  if (typeof roleConfig?.min_readiness === "number" && readiness < roleConfig.min_readiness) {
    warnings.push(`readiness ${readiness} is below role minimum ${roleConfig.min_readiness}`)
  }
  if (roleConfig?.min_maturity) {
    const ladder = Array.isArray(config.maturity_ladder) ? config.maturity_ladder : []
    const currentIndex = ladder.indexOf(thread.maturity)
    const requiredIndex = ladder.indexOf(roleConfig.min_maturity)
    if (currentIndex !== -1 && requiredIndex !== -1 && currentIndex < requiredIndex) {
      warnings.push(`maturity ${thread.maturity} is before role minimum ${roleConfig.min_maturity}`)
    }
  }
  return warnings
}

function loadRtState(directory, role = null) {
  const activePath = join(directory, ".research-trellis", "active.yaml")
  const configPath = join(directory, ".research-trellis", "config.yaml")
  const projectPath = "research/project.md"
  const active = parseSimpleYamlMap(readText(activePath) || "")
  const config = parseConfig(readText(configPath) || "")
  const activeThread = typeof active.active_thread === "string" ? active.active_thread : null

  if (!activeThread) {
    return { activeThread: null, config, projectPath, missing: "No active RT thread. Run rt thread new or rt focus <thread>." }
  }

  const threadPath = `research/${activeThread}/thread.md`
  const threadText = readText(join(directory, threadPath))
  if (!threadText) {
    return { activeThread, config, projectPath, threadPath, missing: `Active RT thread file is missing: ${threadPath}` }
  }

  const thread = parseThreadFrontmatter(threadText)
  const packetPath = role ? `research/${activeThread}/context/${role}.yaml` : null
  const packetExists = packetPath ? existsSync(join(directory, packetPath)) : false
  const roleConfig = role ? config.roles[role] || { warnings: [], prompt: { stop_conditions: [] } } : null
  const warnings = role ? gateWarnings(roleConfig, config, thread) : []

  return { activeThread, config, projectPath, threadPath, thread, packetPath, packetExists, roleConfig, warnings }
}

function buildRoleContext(directory, role) {
  const state = loadRtState(directory, role)
  if (state.missing) {
    return `${RT_MARKER}\n<rt-role-context>\nRole: ${role}\nStatus: ${state.missing}\nBoundary: injector is read-only and did not change RT state.\n</rt-role-context>`
  }

  const warningLines = state.warnings.length > 0 ? state.warnings.map(w => `- ${w}`).join("\n") : "- None detected."
  const packetLine = state.packetExists
    ? `Packet: ${state.packetPath}`
    : `Packet: not generated; run rt pack --role ${role} if a durable packet is needed.`
  const objective = state.roleConfig?.prompt?.objective ? `Objective: ${state.roleConfig.prompt.objective}\n` : ""

  return `${RT_MARKER}\n<rt-role-context>\nRole: ${role}\nActive thread: ${state.activeThread}\nMaturity: ${state.thread.maturity}\nReadiness: ${state.thread.readiness} (${state.thread.readiness_source || "unknown source"})\nProject file: ${state.projectPath}\nThread file: ${state.threadPath}\n${packetLine}\n${objective}\nRole gate warnings:\n${warningLines}\nSafety boundaries:\n- Humans own maturity/readiness; recommend changes, do not apply them.\n- Injector is read-only; it did not mutate thread.md, active.yaml, config.yaml, or packets.\n- Read research/project.md before research/<thread>/thread.md.\n- Treat generated packets as cache, not source of truth.\n- Dreamer must not create implementation tasks or hand work directly to build/Executor.\n</rt-role-context>`
}

function buildMainBreadcrumb(directory) {
  const state = loadRtState(directory)
  if (state.missing) {
    return `<rt-breadcrumb>\nResearch Trellis repo detected. ${state.missing}\nSafe next action: inspect research/project.md, then create/focus a thread.\n</rt-breadcrumb>`
  }
  return `<rt-breadcrumb>\nActive RT thread: ${state.activeThread}\nMaturity: ${state.thread.maturity}\nReadiness: ${state.thread.readiness} (${state.thread.readiness_source || "unknown source"})\nSafe reminders: humans own maturity/readiness; read research/project.md before ${state.threadPath}; use rt orient or rt pack --role <role> before role fan-out.\n</rt-breadcrumb>`
}

function prependTextPart(output, text) {
  const parts = output?.parts || []
  output.parts = parts
  const textPart = parts.find(p => p.type === "text" && typeof p.text === "string")
  if (textPart) {
    textPart.text = `${text}\n\n${textPart.text}`
  } else {
    parts.unshift({ type: "text", text })
  }
}

export default async ({ directory }) => {
  return {
    "tool.execute.before": async (input, output) => {
      try {
        if (process.env.TRELLIS_HOOKS === "0" || process.env.TRELLIS_DISABLE_HOOKS === "1") return
        if (!isRtRepo(directory)) return
        if ((input?.tool || "").toLowerCase() !== "task") return
        const args = output?.args
        if (!args || typeof args !== "object") return
        const config = parseConfig(readText(join(directory, ".research-trellis", "config.yaml")) || "")
        const role = roleFromTaskArgs(args, config)
        if (!role) return
        const originalPrompt = typeof args.prompt === "string" ? args.prompt : ""
        if (originalPrompt.includes(RT_MARKER)) return
        args.prompt = `${buildRoleContext(directory, role)}\n\n---\n\n${originalPrompt}`
      } catch {
        // Best-effort context only; never block OpenCode tool execution.
      }
    },

    "chat.message": async (input, output) => {
      try {
        if (process.env.TRELLIS_HOOKS === "0" || process.env.TRELLIS_DISABLE_HOOKS === "1") return
        if (process.env.OPENCODE_NON_INTERACTIVE === "1") return
        if (!isRtRepo(directory)) return
        if (typeof input?.agent === "string" && /^rt-[A-Za-z0-9_-]+$/.test(input.agent)) return
        prependTextPart(output, buildMainBreadcrumb(directory))
      } catch {
        // Best-effort breadcrumb only; never block chat turns.
      }
    },
  }
}
